import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv, vec3, uniform, time } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    textContent = [],
    cinematicPrimitives = [],
    scenePosition = { x: 0, y: 0, z: 0 },
    intent = {}
  } = config;

  const visualSpec = intent.visualSpec || {};
  const colors = visualSpec.colors || {};
  const gradientStops = colors.gradientStops || [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' }
  ];

  // Root group
  const group = new THREE.Group();
  group.position.set(scenePosition.x || 0, scenePosition.y || 0, scenePosition.z || 0);
  group.rotation.order = 'XYZ';

  // Button dimensions
  const buttonWidth = 2.6;
  const buttonHeight = 0.68;
  const cornerRadius = 0.08;
  const bevelDepth = 0.03;
  const emissiveStrokeWidth = 0.015;

  // --- BUTTON GEOMETRY (rounded rect with bevel) ---
  const buttonGeometry = new THREE.BufferGeometry();
  const vertices = [];
  const indices = [];
  const uvs = [];

  // Helper: rounded rect vertices
  const addRoundedRectVertices = (width, height, radius, depth = 0) => {
    const halfW = width / 2;
    const halfH = height / 2;
    const segments = 8;
    let vertexCount = vertices.length / 3;

    // Corner centers
    const corners = [
      { x: halfW - radius, y: halfH - radius }, // top-right
      { x: -halfW + radius, y: halfH - radius }, // top-left
      { x: -halfW + radius, y: -halfH + radius }, // bottom-left
      { x: halfW - radius, y: -halfH + radius } // bottom-right
    ];

    // Center point
    vertices.push(0, 0, depth);
    const centerIdx = vertexCount;
    uvs.push(0.5, 0.5);
    vertexCount++;

    // Straight edges
    // Top edge
    for (let i = 0; i <= segments; i++) {
      const x = -halfW + radius + (i / segments) * (width - 2 * radius);
      vertices.push(x, halfH, depth);
      uvs.push((x + halfW) / width, 1);
      vertexCount++;
    }

    // Right edge
    for (let i = 0; i <= segments; i++) {
      const y = halfH - radius - (i / segments) * (height - 2 * radius);
      vertices.push(halfW, y, depth);
      uvs.push(1, (halfH - y) / height);
      vertexCount++;
    }

    // Bottom edge
    for (let i = 0; i <= segments; i++) {
      const x = halfW - radius - (i / segments) * (width - 2 * radius);
      vertices.push(x, -halfH, depth);
      uvs.push((x + halfW) / width, 0);
      vertexCount++;
    }

    // Left edge
    for (let i = 0; i <= segments; i++) {
      const y = -halfH + radius + (i / segments) * (height - 2 * radius);
      vertices.push(-halfW, y, depth);
      uvs.push(0, (halfH - y) / height);
      vertexCount++;
    }

    // Corner arcs
    for (let c = 0; c < 4; c++) {
      const corner = corners[c];
      const startAngle = c * Math.PI / 2;
      for (let i = 1; i <= segments; i++) {
        const angle = startAngle + (i / segments) * (Math.PI / 2);
        const x = corner.x + radius * Math.cos(angle);
        const y = corner.y + radius * Math.sin(angle);
        vertices.push(x, y, depth);
        uvs.push((x + halfW) / width, (halfH - y) / height);
        vertexCount++;
      }
    }

    return vertexCount;
  };

  // Front face
  let vertCount = addRoundedRectVertices(buttonWidth, buttonHeight, cornerRadius, 0);

  // Back face (for bevel)
  addRoundedRectVertices(buttonWidth, buttonHeight, cornerRadius, bevelDepth);

  // Build indices for front face and bevel
  const frontCount = vertCount;
  for (let i = 1; i < frontCount; i++) {
    indices.push(0, i, (i % (frontCount - 1)) + 1);
  }

  // Bevel side faces (connect front to back)
  for (let i = 1; i < frontCount; i++) {
    const next = (i % (frontCount - 1)) + 1;
    const backI = frontCount + i;
    const backNext = frontCount + next;
    indices.push(i, next, backI);
    indices.push(next, backNext, backI);
  }

  buttonGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(vertices), 3));
  buttonGeometry.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(uvs), 2));
  buttonGeometry.computeVertexNormals();

  // --- GRADIENT MATERIAL (TSL) ---
  const uv0 = uv();

  // Parse gradient colors
  const parseHex = (hex) => {
    const h = hex.replace('#', '');
    return new THREE.Color(parseInt(h, 16));
  };

  const stops = gradientStops.sort((a, b) => a.at - b.at);
  let gradColor = color(parseHex(stops[0].hex));

  for (let i = 1; i < stops.length; i++) {
    const prevStop = stops[i - 1];
    const currStop = stops[i];
    const t = uniform((currStop.at + prevStop.at) / 2);
    const range = currStop.at - prevStop.at;

    const factor = smoothstep(
      uniform(prevStop.at),
      uniform(currStop.at),
      uv0.y
    );

    gradColor = mix(
      color(parseHex(prevStop.hex)),
      color(parseHex(currStop.hex)),
      factor
    );
  }

  // Hard seam line at y=0.5
  const seamLine = smoothstep(uniform(0.49), uniform(0.5), uv0.y).sub(smoothstep(uniform(0.5), uniform(0.51), uv0.y));

  const material = new MeshStandardNodeMaterial();
  material.colorNode = mix(
    gradColor,
    color(new THREE.Color('#ffffff')),
    seamLine.mul(uniform(0.15))
  );
  material.roughnessNode = uniform(0.5);
  material.metalnessNode = uniform(0.35);
  material.clearcoatNode = uniform(0.22);

  // Emissive perimeter glow
  const perimeter = smoothstep(uniform(0.02), uniform(0), uv0.x)
    .add(smoothstep(uniform(0.98), uniform(1), uv0.x))
    .add(smoothstep(uniform(0.02), uniform(0), uv0.y))
    .add(smoothstep(uniform(0.98), uniform(1), uv0.y));

  material.emissiveNode = mix(
    color(new THREE.Color('#ff2a38')),
    vec3(0),
    smoothstep(uniform(0.015), uniform(0.02), perimeter)
  ).mul(uniform(1.6));

  const buttonMesh = new THREE.Mesh(buttonGeometry, material);
  buttonMesh.castShadow = true;
  buttonMesh.receiveShadow = true;
  group.add(buttonMesh);

  // --- ACCENT RIM LIGHT ---
  const rimLight = new THREE.PointLight(0xff2a38, 1.2, 5);
  rimLight.position.set(1.5, 0.5, 0.4);
  group.add(rimLight);

  // --- CONTACT SHADOW PLANE ---
  const shadowGeometry = new THREE.CircleGeometry(1.5, 32);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new THREE.Color('#000000'),
    transparent: true,
    depthWrite: false
  });
  shadowMaterial.colorNode = mix(
    color(new THREE.Color('#000000')),
    vec3(0),
    uniform(0.65)
  );

  const shadowPlane = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowPlane.position.z = -0.08;
  shadowPlane.castShadow = false;
  shadowPlane.receiveShadow = true;
  group.add(shadowPlane);

  // --- TEXT LABELS ---
  // CTA label: "BEGIN COMMISSION"
  const ctaLabel = ctx.fontAtlas.createText('BEGIN COMMISSION', {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.6
  });
  ctaLabel.position.y = 0;
  ctaLabel.position.z = 0.05;
  group.add(ctaLabel);

  // Caption: "NO DEPOSIT REQUIRED"
  const captionText = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.08
  });
  captionText.position.y = -0.25;
  captionText.position.z = 0.05;
  group.add(captionText);

  // --- MOTION SETUP ---
  const animations = {
    timelines: []
  };

  // Mount settle: scale 1.04 -> 1.0 over 900ms
  const settleTimeline = gsap.timeline({ paused: false });
  settleTimeline.fromTo(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0
  );
  animations.timelines.push(settleTimeline);

  // Hover state variables
  let isHovering = false;
  const hoverState = { emissiveIntensity: 1.6, translateZ: 0 };

  // --- EVENT HANDLERS ---
  group.userData.handlers = {
    onPointerEnter() {
      if (isHovering) return;
      isHovering = true;

      const hoverTimeline = gsap.timeline();
      hoverTimeline.to(
        buttonMesh.position,
        { z: 0.06, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        0
      );
      hoverTimeline.to(
        hoverState,
        { emissiveIntensity: 2.2, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        0
      );

      animations.timelines.push(hoverTimeline);
    },

    onPointerLeave() {
      if (!isHovering) return;
      isHovering = false;

      const leaveTimeline = gsap.timeline();
      leaveTimeline.to(
        buttonMesh.position,
        { z: 0, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        0
      );
      leaveTimeline.to(
        hoverState,
        { emissiveIntensity: 1.6, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        0
      );

      animations.timelines.push(leaveTimeline);
    },

    onPointerDown() {
      const pressTimeline = gsap.timeline();
      pressTimeline.to(
        group.scale,
        { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' },
        0
      );
      pressTimeline.to(
        shadowPlane.position,
        { z: -0.04, duration: 0.12 },
        0
      );
      animations.timelines.push(pressTimeline);
    },

    onPointerUp() {
      const releaseTimeline = gsap.timeline();
      releaseTimeline.to(
        group.scale,
        { x: 1.0, y: 1.0, z: 1.0, duration: 0.2, ease: 'back.out' },
        0
      );
      releaseTimeline.to(
        shadowPlane.position,
        { z: -0.08, duration: 0.2 },
        0
      );
      animations.timelines.push(releaseTimeline);
    }
  };

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    animations.timelines.forEach(tl => tl.kill());
    buttonGeometry.dispose();
    shadowGeometry.dispose();
    material.dispose();
    shadowMaterial.dispose();
  };

  return group;
}
